            change = None
        reported.append(change)
    if overflowed:
        reason += REASON_OVERFLOW_SUFFIX
    return ScoreItem(
        name="Working Capital Efficiency",
        requirement="FR-024",
        value=(("ccc_change", reported[0]), ("dso_change", reported[1])),
