            requirement="FR-025",
            value=change,
            earned=0,
            available=0,
            status=STATUS_NOT_APPLICABLE,
            reason=FR025_NOT_APPLICABLE_REASON,
        )
    return _derived_item("Debt Reduction", "FR-025", FR025_DEBT_REDUCTION, change)


